import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Erasure Code at Scale - Thomas William Byrne","description":"","frontmatter":{"title":"Erasure Code at Scale - Thomas William Byrne","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["Ceph","纠删码","性能优化","存储集群","数据保护"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Erasure_Code_at_Scale_-_Thomas_William_Byrne.md","filePath":"posts/2018/Erasure_Code_at_Scale_-_Thomas_William_Byrne.md","lastUpdated":1780459816000}'),a={name:"posts/2018/Erasure_Code_at_Scale_-_Thomas_William_Byrne.md"};function o(p,l,s,n,_,u){return e(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 英国牛津郡Rutherford Appleton实验室</p><p><strong>参会人员</strong>：</p><ul><li>Ceph研发人员</li><li>大型强子对撞机（LHC）实验相关人员</li><li>高能物理研究所（IHEP）相关人员</li></ul><p><strong>会议主题</strong>：</p><ul><li>Ceph在LHC实验中的存储应用</li><li>Ceph集群的性能优化和问题解决</li><li>Ceph社区对纠删码的支持</li></ul><p><strong>会议内容</strong>：</p><p><strong>一、Ceph在LHC实验中的应用</strong></p><ul><li>LHC实验每年产生约50PB的数据，需要大规模存储系统进行存储和分析。</li><li>Rutherford Appleton实验室负责存储和分析工作，拥有超过30PB的磁盘存储和约10PB的磁带存储。</li><li>研究人员正在使用Ceph替换原有的磁盘存储系统，以提供更高的性能和可扩展性。</li></ul><p><strong>二、Ceph集群的性能优化</strong></p><ul><li>Ceph集群使用纠删码进行数据保护，并采用较大的存储节点（每个节点30+驱动器）。</li><li>研究人员使用Liberator Stripper插件来优化数据分布和性能。</li><li>研究人员通过调整CRUSH映射和放置组大小来优化集群性能。</li></ul><p><strong>三、Ceph集群的问题解决</strong></p><ul><li>研究人员遇到了一些问题，例如： <ul><li>纠删码放置组回填导致的性能问题。</li><li>不一致的放置组导致的数据可用性问题。</li><li>磁盘坏道导致的数据损坏问题。</li></ul></li><li>研究人员通过以下方式解决了这些问题： <ul><li>更新Ceph版本以修复已知问题。</li><li>调整集群配置以优化性能。</li><li>使用手动CRUSH映射编辑来管理集群。</li></ul></li></ul><p><strong>四、Ceph社区的支持</strong></p><ul><li>研究人员对Ceph社区在纠删码支持方面的进展感到满意。</li><li>研究人员希望Ceph社区能够继续改进纠删码的性能和稳定性。</li></ul><p><strong>五、后续行动计划</strong></p><ul><li>研究人员将继续使用Ceph存储系统，并评估其性能和稳定性。</li><li>研究人员将继续与Ceph社区合作，解决集群中存在的问题。</li><li>研究人员将评估Ceph的新功能，并将其应用于集群中。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>纠删码</li><li>CRUSH映射</li><li>放置组</li><li>放置组回填</li><li>不一致的放置组</li><li>磁盘坏道</li><li>数据损坏</li><li>Rutherford Appleton实验室</li><li>LHC实验</li><li>高能物理研究所</li><li>大型存储系统</li><li>数据保护</li><li>性能优化</li><li>数据分布</li></ul>',20)])])}const d=i(a,[["render",o]]);export{C as __pageData,d as default};
